#################################################################
# Disjointness and Equivalence
#################################################################

:Organization owl:disjointWith :Item .
:Amount owl:disjointWith :Price .
:Organization owl:disjointWith :Address .
:Segment owl:disjointWith :CompositeDataElement .
:InvoiceHeader owl:disjointWith :InvoiceDetail .
:InvoiceDetail owl:disjointWith :InvoiceSummary .
:InvoiceHeader owl:disjointWith :InvoiceSummary .

owl:disjointUnionOf ( :InvoiceHeader :InvoiceDetail :InvoiceSummary ) .

#################################################################
# Restrictions (GCAs and Equivalence)
#################################################################

:InvoiceMessage owl:equivalentClass [
  rdf:type owl:Class ;
  owl:Restriction [ owl:onProperty :hasInvoiceHeader ; owl:allValuesFrom :InvoiceHeader ] ;
  owl:Restriction [ owl:onProperty :hasInvoiceDetail ; owl:allValuesFrom :InvoiceDetail ] ;
  owl:Restriction [ owl:onProperty :hasInvoiceSummary ; owl:allValuesFrom :InvoiceSummary ]
] .

:OrganizationRoleAssignment owl:equivalentClass [
  rdf:type owl:Class ;
  owl:Restriction [ owl:onProperty :roleOrganization ; owl:allValuesFrom :Organization ] ;
  owl:Restriction [ owl:onProperty :roleType ; owl:allValuesFrom :AgentRole ]
] .

:InvoiceItemization owl:equivalentClass [
  rdf:type owl:Class ;
  owl:Restriction [ owl:onProperty :itemizationItem ; owl:allValuesFrom :LineItem ]
] .

