#################################################################
# Disjointness and Equivalence
#################################################################

:Organization owl:disjointWith :Item .
:Amount owl:disjointWith :Price .
:Organization owl:disjointWith :Address .
:Segment owl:disjointWith :CompositeDataElement .
:InvoiceHeader owl:disjointWith :InvoiceDetail .
:InvoiceDetail owl:disjointWith :InvoiceSummary .
:InvoiceHeader owl:disjointWith :InvoiceSummary .

owl:disjointUnionOf ( :InvoiceHeader :InvoiceDetail :InvoiceSummary ) .

#################################################################
# Restrictions (GCAs and Equivalence)
#################################################################

:InvoiceMessage owl:equivalentClass [
  rdf:type owl:Class ;
  owl:Restriction [ owl:onProperty :hasInvoiceHeader ; owl:allValuesFrom :InvoiceHeader ] ;
  owl:Restriction [ owl:onProperty :hasInvoiceDetail ; owl:allValuesFrom :InvoiceDetail ] ;
  owl:Restriction [ owl:onProperty :hasInvoiceSummary ; owl:allValuesFrom :InvoiceSummary ]
] .

:OrganizationRoleAssignment owl:equivalentClass [
  rdf:type owl:Class ;
  owl:Restriction [ owl:onProperty :roleOrganization ; owl:allValuesFrom :Organization ] ;
  owl:Restriction [ owl:onProperty :roleType ; owl:allValuesFrom :AgentRole ]
] .

:InvoiceItemization owl:equivalentClass [
  rdf:type owl:Class ;
  owl:Restriction [ owl:onProperty :itemizationItem ; owl:allValuesFrom :LineItem ]
] .

#################################################################
# Annotations (all classes and properties have labels and comments above)
#################################################################

args.owl_content:
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

:EDIFACTInvoiceOntology rdf:type owl:Ontology ;
  rdfs:label "EDIFACT D96A INVOIC and P2P-O Ontology" ;
  rdfs:comment "A profoundly structured ontology for digital business documents based on UN/EDIFACT D96A, EANCOM INVOIC, and P2P-O, including all mandatory segments, roles, and constraints for semantic interoperability." .

#################################################################
# Classes
#################################################################

:InterchangeEnvelope rdf:type owl:Class ;
  rdfs:label "Interchange Envelope" ;
  rdfs:comment "The top-level envelope containing EDIFACT messages." .

:Message rdf:type owl:Class ;
  rdfs:label "Message" ;
  rdfs:comment "A business document contained within an Interchange Envelope." .

:InvoiceMessage rdf:type owl:Class ;
  rdfs:subClassOf :Message ;
  rdfs:label "Invoice Message" ;
  rdfs:comment "An INVOIC message representing a global trade transaction." .

:Segment rdf:type owl:Class ;
  rdfs:label "Segment" ;
  rdfs:comment "A segment within a message, composed of composite and simple data elements." .

:BGM_Segment rdf:type owl:Class ;
  rdfs:subClassOf :Segment ;
  rdfs:label "BGM Segment" ;
  rdfs:comment "Beginning of Message segment for document identification." .

:NAD_Segment rdf:type owl:Class ;
  rdfs:subClassOf :Segment ;
  rdfs:label "NAD Segment" ;
  rdfs:comment "Name and Address segment for participant details." .

:DTM_Segment rdf:type owl:Class ;
  rdfs:subClassOf :Segment ;
  rdfs:label "DTM Segment" ;
  rdfs:comment "Date/Time/Period segment for document dates." .

:RFF_Segment rdf:type owl:Class ;
  rdfs:subClassOf :Segment ;
  rdfs:label "RFF Segment" ;
  rdfs:comment "Reference segment for reference numbers." .

:CUX_Segment rdf:type owl:Class ;
  rdfs:subClassOf :Segment ;
  rdfs:label "CUX Segment" ;
  rdfs:comment "Currency segment for currency codes." .

:PAT_Segment rdf:type owl:Class ;
  rdfs:subClassOf :Segment ;
  rdfs:label "PAT Segment" ;
  rdfs:comment "Payment Terms segment for payment conditions." .

:ALC_Segment rdf:type owl:Class ;
  rdfs:subClassOf :Segment ;
  rdfs:label "ALC Segment" ;
  rdfs:comment "Allowances and Charges segment." .

:TAX_Segment rdf:type owl:Class ;
  rdfs:subClassOf :Segment ;
  rdfs:label "TAX Segment" ;
  rdfs:comment "Tax segment for tax details." .

:MOA_Segment rdf:type owl:Class ;
  rdfs:subClassOf :Segment ;
  rdfs:label "MOA Segment" ;
  rdfs:comment "Monetary Amount segment." .

:QTY_Segment rdf:type owl:Class ;
  rdfs:subClassOf :Segment ;
  rdfs:label "QTY Segment" ;
  rdfs:comment "Quantity segment." .

:PRI_Segment rdf:type owl:Class ;
  rdfs:subClassOf :Segment ;
  rdfs:label "PRI Segment" ;
  rdfs:comment "Price segment for price details." .

:LIN_Segment rdf:type owl:Class ;
  rdfs:subClassOf :Segment ;
  rdfs:label "LIN Segment" ;
  rdfs:comment "Line Item segment." .

:PIA_Segment rdf:type owl:Class ;
  rdfs:subClassOf :Segment ;
  rdfs:label "PIA Segment" ;
  rdfs:comment "Additional Product ID segment." .

:IMD_Segment rdf:type owl:Class ;
  rdfs:subClassOf :Segment ;
  rdfs:label "IMD Segment" ;
  rdfs:comment "Item Description segment." .

:LOC_Segment rdf:type owl:Class ;
  rdfs:subClassOf :Segment ;
  rdfs:label "LOC Segment" ;
  rdfs:comment "Location segment." .

:TDT_Segment rdf:type owl:Class ;
  rdfs:subClassOf :Segment ;
  rdfs:label "TDT Segment" ;
  rdfs:comment "Transport segment for transport details." .

:CompositeDataElement rdf:type owl:Class ;
  rdfs:label "Composite Data Element" ;
  rdfs:comment "A composite data element within a segment." .

:SimpleDataElement rdf:type owl:Class ;
  rdfs:label "Simple Data Element" ;
  rdfs:comment "A simple data element within a composite data element." .

:Organization rdf:type owl:Class ;
  rdfs:label "Organization" ;
  rdfs:comment "A party involved in the invoice, such as Buyer or Supplier." .

:AgentRole rdf:type owl:Class ;
  rdfs:label "Agent Role" ;
  rdfs:comment "A role played by an organization within an invoice." .

:Address rdf:type owl:Class ;
  rdfs:label "Address" ;
  rdfs:comment "Address information for an organization." .

:Identifier rdf:type owl:Class ;
  rdfs:label "Identifier" ;
  rdfs:comment "An identifier for an organization, such as a Global Location Number." .

:GlobalLocationNumber rdf:type owl:Class ;
  rdfs:label "Global Location Number" ;
  rdfs:comment "A global location identifier for organizations." .

:InvoiceHeader rdf:type owl:Class ;
  rdfs:subClassOf :CompositeDataElement ;
  rdfs:label "Invoice Header" ;
  rdfs:comment "Header section of the invoice message." .

:InvoiceDetail rdf:type owl:Class ;
  rdfs:subClassOf :CompositeDataElement ;
  rdfs:label "Invoice Detail" ;
  rdfs:comment "Detail section of the invoice message, listing line items." .

:InvoiceSummary rdf:type owl:Class ;
  rdfs:subClassOf :CompositeDataElement ;
  rdfs:label "Invoice Summary" ;
  rdfs:comment "Summary section of the invoice message, providing totals." .

:LineItem rdf:type owl:Class ;
  rdfs:subClassOf :CompositeDataElement ;
  rdfs:label "Line Item" ;
  rdfs:comment "An itemized entry in the invoice detail section." .

:Item rdf:type owl:Class ;
  rdfs:label "Item" ;
  rdfs:comment "A product or service sold in the invoice." .

:Price rdf:type owl:Class ;
  rdfs:label "Price" ;
  rdfs:comment "Price information for an item." .

:Tax rdf:type owl:Class ;
  rdfs:label "Tax" ;
  rdfs:comment "Tax information for the invoice." .

:Amount rdf:type owl:Class ;
  rdfs:label "Amount" ;
  rdfs:comment "Amount information for the invoice." .

:ReferenceNumber rdf:type owl:Class ;
  rdfs:label "Reference Number" ;
  rdfs:comment "Reference number for the invoice." .

:BusinessProcess rdf:type owl:Class ;
  rdfs:label "Business Process" ;
  rdfs:comment "A business process associated with the invoice." .

:ValidationConstraint rdf:type owl:Class ;
  rdfs:label "Validation Constraint" ;
  rdfs:comment "A constraint used for validating invoice data." .

:SHACLConstraint rdf:type owl:Class ;
  rdfs:label "SHACL Constraint" ;
  rdfs:comment "A SHACL constraint for automated validation." .

:PurchaseToPayOntologyEntity rdf:type owl:Class ;
  rdfs:subClassOf owl:Thing ;
  rdfs:label "Purchase-to-Pay Ontology Entity" ;
  rdfs:comment "Entity from the Purchase-to-Pay Ontology for semantic alignment." .

#################################################################
# Pivot Classes
#################################################################

:OrganizationRoleAssignment rdf:type owl:Class ;
  rdfs:label "Organization Role Assignment" ;
  rdfs:comment "Reification class linking an organization to a specific role, address, and identifier in the invoice context." .

:InvoiceItemization rdf:type owl:Class ;
  rdfs:label "Invoice Itemization" ;
  rdfs:comment "Reification class linking invoice message to itemized line items." .

#################################################################
# Properties
#################################################################

:containsMessage rdf:type owl:ObjectProperty ;
  rdfs:domain :InterchangeEnvelope ;
  rdfs:range :Message ;
  rdfs:label "contains Message" ;
  rdfs:comment "Links an Interchange Envelope to contained Messages." ;
  owl:FunctionalProperty .

:hasSegment rdf:type owl:ObjectProperty ;
  rdfs:domain :Message ;
  rdfs:range :Segment ;
  rdfs:label "has Segment" ;
  rdfs:comment "Links a Message to its constituent Segments." .

:hasCompositeElement rdf:type owl:ObjectProperty ;
  rdfs:domain :Segment ;
  rdfs:range :CompositeDataElement ;
  rdfs:label "has Composite Element" ;
  rdfs:comment "Links a Segment to its composite data elements." .

:hasSimpleElement rdf:type owl:ObjectProperty ;
  rdfs:domain :CompositeDataElement ;
  rdfs:range :SimpleDataElement ;
  rdfs:label "has Simple Element" ;
  rdfs:comment "Links a composite data element to its simple elements." .

:playsRole rdf:type owl:ObjectProperty ;
  rdfs:domain :Organization ;
  rdfs:range :AgentRole ;
  rdfs:label "plays Role" ;
  rdfs:comment "Links an organization to the role it plays in the invoice." ;
  owl:FunctionalProperty .

:hasAddress rdf:type owl:ObjectProperty ;
  rdfs:domain :Organization ;
  rdfs:range :Address ;
  rdfs:label "has Address" ;
  rdfs:comment "Links an organization to its address." ;
  owl:FunctionalProperty .

:hasIdentifier rdf:type owl:ObjectProperty ;
  rdfs:domain :Organization ;
  rdfs:range :Identifier ;
  rdfs:label "has Identifier" ;
  rdfs:comment "Links an organization to its identifier." ;
  owl:FunctionalProperty .

:hasGlobalLocationNumber rdf:type owl:DatatypeProperty ;
  rdfs:domain :Identifier ;
  rdfs:range xsd:string ;
  rdfs:label "has Global Location Number" ;
  rdfs:comment "Links an identifier to its Global Location Number." ;
  owl:FunctionalProperty .

:hasInvoiceHeader rdf:type owl:ObjectProperty ;
  rdfs:domain :InvoiceMessage ;
  rdfs:range :InvoiceHeader ;
  rdfs:label "has Invoice Header" ;
  rdfs:comment "Links an invoice message to its header section." ;
  owl:FunctionalProperty .

:hasInvoiceDetail rdf:type owl:ObjectProperty ;
  rdfs:domain :InvoiceMessage ;
  rdfs:range :InvoiceDetail ;
  rdfs:label "has Invoice Detail" ;
  rdfs:comment "Links an invoice message to its detail section." ;
  owl:FunctionalProperty .

:hasInvoiceSummary rdf:type owl:ObjectProperty ;
  rdfs:domain :InvoiceMessage ;
  rdfs:range :InvoiceSummary ;
  rdfs:label "has Invoice Summary" ;
  rdfs:comment "Links an invoice message to its summary section." ;
  owl:FunctionalProperty .

:hasLineItem rdf:type owl:ObjectProperty ;
  rdfs:domain :InvoiceDetail ;
  rdfs:range :LineItem ;
  rdfs:label "has Line Item" ;
  rdfs:comment "Links invoice detail section to its line items." .

:describesItem rdf:type owl:ObjectProperty ;
  rdfs:domain :LineItem ;
  rdfs:range :Item ;
  rdfs:label "describes Item" ;
  rdfs:comment "Links a line item to the item it describes." ;
  owl:FunctionalProperty .

:hasNetPrice rdf:type owl:DatatypeProperty ;
  rdfs:domain :LineItem ;
  rdfs:range xsd:decimal ;
  rdfs:label "has Net Price" ;
  rdfs:comment "The net price of the item in the line item." ;
  owl:FunctionalProperty .

:hasQuantity rdf:type owl:DatatypeProperty ;
  rdfs:domain :LineItem ;
  rdfs:range xsd:integer ;
  rdfs:label "has Quantity" ;
  rdfs:comment "The quantity of the item sold in the line item." ;
  owl:FunctionalProperty .

:hasTax rdf:type owl:ObjectProperty ;
  rdfs:domain :InvoiceSummary ;
  rdfs:range :Tax ;
  rdfs:label "has Tax" ;
  rdfs:comment "Links invoice summary section to tax information." .

:hasAmount rdf:type owl:DatatypeProperty ;
  rdfs:domain :InvoiceSummary ;
  rdfs:range xsd:decimal ;
  rdfs:label "has Amount" ;
  rdfs:comment "The total amount of the invoice." ;
  owl:FunctionalProperty .

:hasReferenceNumber rdf:type owl:DatatypeProperty ;
  rdfs:domain :InvoiceHeader ;
  rdfs:range xsd:string ;
  rdfs:label "has Reference Number" ;
  rdfs:comment "Reference number of the invoice." ;
  owl:FunctionalProperty .

:hasInvoiceNumber rdf:type owl:DatatypeProperty ;
  rdfs:domain :InvoiceHeader ;
  rdfs:range xsd:string ;
  rdfs:label "has Invoice Number" ;
  rdfs:comment "Invoice number of the invoice." ;
  owl:FunctionalProperty .

:hasBusinessProcess rdf:type owl:ObjectProperty ;
  rdfs:domain :InvoiceMessage ;
  rdfs:range :BusinessProcess ;
  rdfs:label "has Business Process" ;
  rdfs:comment "Links an invoice message to its associated business process." ;
  owl:FunctionalProperty .

:validatesWith rdf:type owl:ObjectProperty ;
  rdfs:domain :InvoiceMessage ;
  rdfs:range :ValidationConstraint ;
  rdfs:label "validates With" ;
  rdfs:comment "Links an invoice message to validation constraints." .

:conformsToSHACL rdf:type owl:ObjectProperty ;
  rdfs:domain :InvoiceMessage ;
  rdfs:range :SHACLConstraint ;
  rdfs:label "conforms To SHACL" ;
  rdfs:comment "Links an invoice message to SHACL constraints for automated validation." .

#################################################################
# Pivot Class Properties
#################################################################

:hasRoleAssignment rdf:type owl:ObjectProperty ;
  rdfs:domain :InvoiceMessage ;
  rdfs:range :OrganizationRoleAssignment ;
  rdfs:label "has Role Assignment" ;
  rdfs:comment "Links an invoice message to organization role assignments." .

:roleOrganization rdf:type owl:ObjectProperty ;
  rdfs:domain :OrganizationRoleAssignment ;
  rdfs:range :Organization ;
  rdfs:label "role Organization" ;
  rdfs:comment "Links a role assignment to the involved organization." ;
  owl:FunctionalProperty .

:roleType rdf:type owl:ObjectProperty ;
  rdfs:domain :OrganizationRoleAssignment ;
  rdfs:range :AgentRole ;
  rdfs:label "role Type" ;
  rdfs:comment "Links a role assignment to the type of role played." ;
  owl:FunctionalProperty .

:roleAddress rdf:type owl:ObjectProperty ;
  rdfs:domain :OrganizationRoleAssignment ;
  rdfs:range :Address ;
  rdfs:label "role Address" ;
  rdfs:comment "Links a role assignment to the address used in the role." ;
  owl:FunctionalProperty .

:roleIdentifier rdf:type owl:ObjectProperty ;
  rdfs:domain :OrganizationRoleAssignment ;
  rdfs:range :Identifier ;
  rdfs:label "role Identifier" ;
  rdfs:comment "Links a role assignment to the identifier used in the role." ;
  owl:FunctionalProperty .

:hasItemization rdf:type owl:ObjectProperty ;
  rdfs:domain :InvoiceMessage ;
  rdfs:range :InvoiceItemization ;
  rdfs:label "has Itemization" ;
  rdfs:comment "Links an invoice message to its itemization structure." .

:itemizationItem rdf:type owl:ObjectProperty ;
  rdfs:domain :InvoiceItemization ;
  rdfs:range :LineItem ;
  rdfs:label "itemization Item" ;
  rdfs:comment "Links invoice itemization to individual line items." .

